    { t: 'fill', q: '【Trung bình】Điền từ theo bài.', items: [['外国一般称研究中国文化的学者为“___家”。', '汉学'], ['“震”为“秦”的音转，“旦”乃“___”的简称。', '斯坦'], ['唐代的中国国势___，名声很大。', '强盛']] },
    { t: 'open', q: '【Nâng cao】Trả lời câu hỏi.', items: [['为什么外国人把中国人叫“唐人”？', '因为唐代中国国势强盛，名声很大，此后外国便有称中国为“唐”的习惯，如“唐人街”“唐人”。'], ['关于“支那”的来源有哪几种说法？', '一是“秦”的音转；二是“荆乐”的转音；三是“此翻为思维”；四是“此云文物国”。'], ['你的国家的语言里怎样称呼中国？这个称呼可能是怎么来的？', '（Gợi ý）Tiếng Việt gọi là “Trung Quốc” (âm Hán Việt của 中国); tiếng Anh China, có thuyết cho là từ “秦”.']] }
